        jsonMap.entrySet().stream().sorted(Comparator.comparing(entry -> ((ResourceLocation)entry.getKey()).toString())).forEach(entry -> IvyTradeReloadListener.parseFile((ResourceLocation)entry.getKey(), (JsonElement)entry.getValue(), parsed));
