            parsed.addAll(IvyTradeRegistry.parseOfferSources(fileId, root));
        }
        catch (Exception exception) {
            SaintsDragonsCommon.LOGGER.error("Failed to parse Ivy trade file {}", (Object)fileId, (Object)exception);
        }
    }
}

