import org.jetbrains.annotations.NotNull;

public class LootTableInjectorModifier
extends LootModifier {
    public static final Codec<LootTableInjectorModifier> CODEC = RecordCodecBuilder.create(instance -> LootTableInjectorModifier.codecStart((RecordCodecBuilder.Instance)instance).apply((Applicative)instance, LootTableInjectorModifier::new));

    public LootTableInjectorModifier(LootItemCondition[] conditions) {
        super(conditions);
    }

    @NotNull
    protected ObjectArrayList<ItemStack> doApply(ObjectArrayList<ItemStack> generatedLoot, LootContext context) {
        CommonAssetsManager manager = CommonAssetsManager.getInstance();
        if (manager == null) {
            return generatedLoot;
        }
        ResourceLocation lootTableId = context.getQueriedLootTableId();
        List<LootTableInjection> injections = manager.getLootTableInjections(lootTableId);
        if (injections.isEmpty()) {
            return generatedLoot;
        }
        for (LootTableInjection injection : injections) {
            for (ItemStack stack : injection.createStacks(context)) {
                generatedLoot.add((Object)stack);
            }
        }
        return generatedLoot;
    }

    public Codec<? extends IGlobalLootModifier> codec() {
        return (Codec)ModLootModifiers.LOOT_TABLE_INJECTOR.get();
    }
}

